mapper.select:
SELECT EXISTS (
  SELECT 1 FROM strategy_executions
  WHERE strategy_id = #{strategyId}
    AND quote_event_id = #{quoteEventId, typeHandler=com.team5.notifications.mapper.UuidTypeHandler}
)

mapper.insert:
INSERT INTO strategy_executions (
  strategy_id, quote_event_id, signal, outcome, quote_price, order_price, quantity,
  idempotency_key, order_id, detail, created_at
) VALUES (
  #{strategyId},
  #{quoteEventId, typeHandler=com.team5.notifications.mapper.UuidTypeHandler},
  #{signal}, #{outcome}, #{quotePrice}, #{orderPrice}, #{quantity},
  #{idempotencyKey}, #{orderId}, #{detail}, #{createdAt}
)

mapper.select:
SELECT execution_id, strategy_id, quote_event_id, signal, outcome, quote_price, order_price,
       quantity, idempotency_key, order_id, detail, created_at
FROM strategy_executions
WHERE strategy_id = #{strategyId}
ORDER BY created_at DESC, execution_id DESC
LIMIT #{limit}
